import{_ as t,o as r,c as o,a2 as s}from"./chunks/framework.BXA5Pi9t.js";const d=JSON.parse('{"title":"Ceph Crimson/Seastore Meeting 2023-03-22","description":"","frontmatter":{"title":"Ceph Crimson/Seastore Meeting 2023-03-22","date":"2023-03-22T00:00:00.000Z","updated":"2023-03-23T00:00:00.000Z","tags":["Ceph","分布式存储","代码审查","开发进展","内存优化"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2023/Ceph_Crimson_Seastore_Meeting_2023-03-22.md","filePath":"posts/2023/Ceph_Crimson_Seastore_Meeting_2023-03-22.md","lastUpdated":1780459816000}'),n={name:"posts/2023/Ceph_Crimson_Seastore_Meeting_2023-03-22.md"};function i(l,e,a,p,_,u){return r(),o("div",null,[...e[0]||(e[0]=[s("<p>本次Ceph Crimson/Seastore会议于2023年3月22日举行，主要讨论了以下议题：</p><p><strong>主要议题：</strong></p><ol><li><strong>代码审查与开发进展</strong><ul><li><strong>scrub 和 aerator 代码迁移</strong>：会议开始时，提到了正在进行的工作，包括对 scrub 和 aerator 代码的审查，以及将 interruptable future 代码迁移到标准协程（co-routine）的工作。讨论了这种迁移可能带来的便利性和效率提升。</li><li><strong>协程与 Future 的使用</strong>：讨论了将现有代码中的 Future 实现转换为协程的可能性。强调了这种转换是可选的，主要为了减少内存分配，提高性能。同时，现有代码不需要强制转换，可以自由混合使用两种风格。</li><li><strong>Shaded 存储接口定义</strong>：讨论了定义 Shaded future store 接口和 Shaded c-store 设备接口的工作，并请求对新的 future store 接口从 OSD 角度进行审查。</li><li><strong>Marco 系统 PR 修改</strong>：根据 AC 的评论，对 Marco 系统的 PR 进行了修改，包括未来写入扭曲和过滤包装短安装的耦合接口定义。讨论了设备接口定义，并计划将其修改为设备类和共享设备类。</li><li><strong>LBA point rpr 代码修改</strong>：报告了 LBA point rpr 代码修改的调试进展，预计本周可以替换现有代码。同时，审查了由某人提交的正在进行中的缓存 PR。</li><li><strong>systore Clone 方法论讨论</strong>：与 Ian 讨论了 systore Clone 的方法论，并开始着手开发原型。</li></ul></li></ol><p><strong>决定事项：</strong></p><ul><li>对 Shaded future store 接口进行进一步审查。</li><li>继续进行 LBA point rpr 代码的调试和替换工作。</li><li>开始 systore Clone 的原型开发。</li></ul><p><strong>后续行动计划：</strong></p><ul><li>完成 Shaded future store 接口的审查并根据反馈进行调整。</li><li>完成 LBA point rpr 代码的调试，并替换现有代码。</li><li>继续开发 systore Clone 的原型，并根据需要进行调整。</li></ul><p>本次会议是一个简短的会议，但涵盖了重要的开发进展和后续的行动计划。</p>",8)])])}const C=t(n,[["render",i]]);export{d as __pageData,C as default};
